const CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function AtomicModelsPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level']);\n  const [mobileControlsOpen, setMobileControlsOpen] = useState(false);\n\n  const [model, setModel] = useState<AtomicModel>('thomson');\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showOrbits, setShowOrbits] = useState(true);\n  const [showNucleus, setShowNucleus] = useState(true);\n  const [showElectrons, setShowElectrons] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showEnergyLevels, setShowEnergyLevels] = useState(true);\n  const [showSpectrum, setShowSpectrum] = useState(true);\n  const [showLabels, setShowLabels] = useState(true);\n  const [showSpin, setShowSpin] = useState(false);\n  const [showFineStructure, setShowFineStructure] = useState(false);\n  const [showZeeman, setShowZeeman] = useState(false);\n  const [magneticField, setMagneticField] = useState(0);\n  const [nQuantum, setNQuantum] = useState(1);\n  const [lQuantum, setLQuantum] = useState(0);\n  const [mQuantum, setMQuantum] = useState(0);\n  const [protonCount, setProtonCount] = useState(1);\n  const [neutronCount, setNeutronCount] = useState(0);\n  const [electronCount, setElectronCount] = useState(1);\n  const [alphaEnergy, setAlphaEnergy] = useState(5);\n\n  const [screening,setScreening]=useState(0);\n  useEffect(()=>{setScreening(s=>Math.min(s,Math.max(0,protonCount-1)));},[protonCount]);\n  const params: AtomicParams = {\n    model, speed, zoom, screening:Math.min(screening,Math.max(0,protonCount-1)), showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure,\n    showZeeman, magneticField, nQuantum, lQuantum, mQuantum,\n    protonCount, neutronCount, electronCount, alphaEnergy,\n  };\n\n  const [liveStats, setLiveStats] = useState({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = ATOMIC_PRESETS[presetIdx];\n    if (!preset) return;\n    setModel(preset.model);\n    const pp = preset.params;\n    setScreening(pp.screening??0);\n    if (pp.speed !== undefined) setSpeed(pp.speed);\n    if (pp.zoom !== undefined) setZoom(pp.zoom);\n    if (pp.showOrbits !== undefined) setShowOrbits(pp.showOrbits);\n    if (pp.showNucleus !== undefined) setShowNucleus(pp.showNucleus);\n    if (pp.showElectrons !== undefined) setShowElectrons(pp.showElectrons);\n    if (pp.showProbability !== undefined) setShowProbability(pp.showProbability);\n    if (pp.showEnergyLevels !== undefined) setShowEnergyLevels(pp.showEnergyLevels);\n    if (pp.showSpectrum !== undefined) setShowSpectrum(pp.showSpectrum);\n    if (pp.showLabels !== undefined) setShowLabels(pp.showLabels);\n    if (pp.showSpin !== undefined) setShowSpin(pp.showSpin);\n    if (pp.showFineStructure !== undefined) setShowFineStructure(pp.showFineStructure);\n    if (pp.showZeeman !== undefined) setShowZeeman(pp.showZeeman);\n    if (pp.magneticField !== undefined) setMagneticField(pp.magneticField);\n    if (pp.nQuantum !== undefined) setNQuantum(pp.nQuantum);\n    if (pp.lQuantum !== undefined) setLQuantum(pp.lQuantum);\n    if (pp.mQuantum !== undefined) setMQuantum(pp.mQuantum);\n    if (pp.protonCount !== undefined) setProtonCount(pp.protonCount);\n    if (pp.neutronCount !== undefined) setNeutronCount(pp.neutronCount);\n    if (pp.electronCount !== undefined) setElectronCount(pp.electronCount);\n    if (pp.alphaEnergy !== undefined) setAlphaEnergy(pp.alphaEnergy);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  useEffect(() => {\n    if (!validQuantumNumbers(nQuantum, lQuantum, mQuantum)) {\n      const validL = possibleLValues(nQuantum);\n      if (!validL.includes(lQuantum)) { setLQuantum(validL[0]); setMQuantum(0); }\n    }\n  }, [nQuantum]);\n\n  useEffect(() => {\n    const validM = possibleMValues(lQuantum);\n    if (!validM.includes(mQuantum)) setMQuantum(validM[0]);\n  }, [lQuantum]);\n\n  const spectrum = useMemo(() => generateHydrogenSpectrum(7), []);\n  const modelLabels: Record<AtomicModel, string> = { thomson: 'Thomson (1897)', rutherford: 'Rutherford (1911)', bohr: 'Bohr (1913)', quantum: 'Quantum (1926)' };\n\n  useTopicPreset(\"simulations-atomic-models\", { \"speed\": setSpeed,\n    \"zoom\": setZoom,\n    \"protonCount\": setProtonCount,\n    \"neutronCount\": setNeutronCount,\n    \"alphaEnergy\": setAlphaEnergy,\n    \"magneticField\": setMagneticField,\n    \"nQuantum\": setNQuantum }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Atomic Physics — From Plum Pudding to Quantum Field Theory</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Atomic Models</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {Object.keys(CC).map(c => (\n                  <button key={c} onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Thomson → Rutherford → Bohr → Schrödinger</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">Eₙ = -13.6 Z²/n² eV</span>\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => (\n              <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n                className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[140px] ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                <p className=\"text-xs font-medium\">{modelLabels[m]}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {ATOMIC_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <AtomicModelsCanvas key={resetKey} params={params} onZoomChange={setZoom} onParamsChange={patch=>{if(patch.protonCount!==undefined)setProtonCount(patch.protonCount);if(patch.showOrbits!==undefined)setShowOrbits(patch.showOrbits);if(patch.showElectrons!==undefined)setShowElectrons(patch.showElectrons);if(patch.showNucleus!==undefined)setShowNucleus(patch.showNucleus);if(patch.showEnergyLevels!==undefined)setShowEnergyLevels(patch.showEnergyLevels);if(patch.showLabels!==undefined)setShowLabels(patch.showLabels);if(patch.showSpin!==undefined)setShowSpin(patch.showSpin);if(patch.showSpectrum!==undefined)setShowSpectrum(patch.showSpectrum);if(patch.showFineStructure!==undefined)setShowFineStructure(patch.showFineStructure);if(patch.showZeeman!==undefined)setShowZeeman(patch.showZeeman);if(patch.magneticField!==undefined)setMagneticField(patch.magneticField);if(patch.screening!==undefined)setScreening(patch.screening);if(patch.showProbability!==undefined)setShowProbability(patch.showProbability);if(patch.nQuantum!==undefined)setNQuantum(patch.nQuantum);if(patch.lQuantum!==undefined)setLQuantum(patch.lQuantum);if(patch.mQuantum!==undefined)setMQuantum(patch.mQuantum);}} isRunning={isRunning} isPaused={isPaused} onModelChange={setModel} onSpeedChange={setSpeed} controls={{run:()=>{setIsRunning(true);setIsPaused(false);},pause:()=>setIsPaused(v=>!v),reset}} onTick={handleTick} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/atomic-models\" title=\"Atomic Models\"\n                  params={{ model, speed, zoom, S:screening, orbits: showOrbits ? 1 : 0, nucleus: showNucleus ? 1 : 0, electrons: showElectrons ? 1 : 0, prob: showProbability ? 1 : 0, levels: showEnergyLevels ? 1 : 0, spectrum: showSpectrum ? 1 : 0, labels: showLabels ? 1 : 0, spin: showSpin ? 1 : 0, fs: showFineStructure ? 1 : 0, zeeman: showZeeman ? 1 : 0, B: magneticField, n: nQuantum, l: lQuantum, m: mQuantum, Z: protonCount, N: neutronCount, e: electronCount, alphaE: alphaEnergy }} />\n              </div>\n\n              {/* Mobile controls toggle */}\n              <div data-stage-role=\"parameters\"><button onClick={() => setMobileControlsOpen(o => !o)} className=\"lg:hidden w-full py-2.5 text-sm font-medium rounded-xl border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 transition\">\n                {mobileControlsOpen ? 'Hide controls ▲' : 'Show controls ▼'}\n              </button></div>\n\n              <div data-stage-role=\"parameters\" className={`rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4 ${mobileControlsOpen ? '' : 'hidden lg:block'}`}>\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Display</p>\n                    <Slider label=\"Animation speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" note=\"Time evolution speed\" />\n                    <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" note=\"Magnification: drag the view to pan; Fit restores framing.\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Nucleus</p>\n                    <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" note=\"Atomic number\" />\n                    <Slider label=\"Neutrons N\" unit=\"\" value={neutronCount} min={0} max={150} step={1} set={setNeutronCount} color=\"#a78bfa\" note=\"Neutron number\" />\n                  </div>\n                </div>\n\n                {model === 'rutherford' && (\n                  <div className=\"border-t border-gray-100 pt-3\">\n                    <Slider label=\"α-particle energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" note=\"Kinetic energy of incoming α particles\" />\n                  </div>\n                )}\n\n                {model === 'bohr' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Bohr Model Options</p>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showOrbits} onChange={e => setShowOrbits(e.target.checked)} className=\"rounded\" /> Show orbits</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showEnergyLevels} onChange={e => setShowEnergyLevels(e.target.checked)} className=\"rounded\" /> Energy levels</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpectrum} onChange={e => setShowSpectrum(e.target.checked)} className=\"rounded\" /> Spectrum bar</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpin} onChange={e => setShowSpin(e.target.checked)} className=\"rounded\" /> Show spin (↑)</label>\n                    </div>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showFineStructure} onChange={e => setShowFineStructure(e.target.checked)} className=\"rounded\" /> Fine structure (j = l ± ½)</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showZeeman} onChange={e => setShowZeeman(e.target.checked)} className=\"rounded\" /> Zeeman effect</label>\n                    </div>\n                    {showZeeman && <Slider label=\"Magnetic field B\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" note=\"Tesla — splits degenerate levels\" />}\n                  </div>\n                )}\n\n                {model === 'quantum' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-purple-600 uppercase tracking-wide\">Quantum Numbers</p>\n                    <div className=\"grid grid-cols-3 gap-3\">\n                      <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" note=\"Principal quantum number\" />\n                      <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" note=\"Angular momentum (0=s,1=p,2=d,3=f)\" />\n                      <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" note=\"Magnetic quantum number\" />\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">Orbital: <span className=\"font-medium text-indigo-600\">{nQuantum}{['s','p','d','f'][lQuantum] || '?'}</span> — <span className=\"text-gray-500\">{lQuantum === 0 ? 'spherical, no angular nodes' : lQuantum === 1 ? 'dumbbell, 1 angular node' : lQuantum === 2 ? 'cloverleaf, 2 angular nodes' : lQuantum === 3 ? 'complex 8-lobed, 3 angular nodes' : 'higher orbital'}</span></p>\n                  </div>\n                )}\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Visibility</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" /> Nucleus</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" /> Electrons</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" /> Probability cloud</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" /> Info labels</label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {model === 'bohr' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={liveStats.energy.toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Radius rₙ\" value={liveStats.radius.toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Velocity vₙ\" value={liveStats.velocity.toFixed(4)} unit=\"c·α\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Quantum n\" value={liveStats.n.toString()} unit=\"\" color=\"text-blue-500\" />\n                      {liveStats.wavelength > 0 && <StatRow label=\"λ (transition)\" value={liveStats.wavelength.toFixed(1)} unit=\"nm\" color=\"text-amber-600\" />}\n                      {showFineStructure && <StatRow label=\"Fine split\" value={(fineSeparation(Math.max(2,liveStats.n),effectiveCharge(protonCount,screening).Zeff)*1e6).toFixed(2)} unit=\"μeV\" color=\"text-purple-600\" />}\n                      {showZeeman && magneticField > 0 && <StatRow label=\"Zeeman ΔE\" value={(magneticField * 5.788e-5 * 1e6).toFixed(2)} unit=\"μeV\" color=\"text-pink-500\" />}\n                    </>\n                  )}\n                  {model === 'quantum' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={bohrEnergy(nQuantum, protonCount).toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Bohr radius\" value={bohrRadius(nQuantum, protonCount).toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Degeneracy\" value={(nQuantum * nQuantum).toString()} unit=\"states\" color=\"text-purple-600\" />\n                      <StatRow label=\"Orbital\" value={`${nQuantum}${['s','p','d','f'][lQuantum] || '?'}`} unit=\"\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Angular nodes\" value={lQuantum.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Radial nodes\" value={(nQuantum - lQuantum - 1).toString()} unit=\"\" color=\"text-blue-500\" />\n                    </>\n                  )}\n                  {model === 'thomson' && (\n                    <>\n                      <StatRow label=\"Electrons\" value={electronCount.toString()} unit=\"\" color=\"text-blue-500\" />\n                      <StatRow label=\"Protons\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Net charge\" value=\"0\" unit=\"e\" color=\"text-emerald-600\" />\n                    </>\n                  )}\n                  {model === 'rutherford' && (\n                    <>\n                      <StatRow label=\"Nucleus Z\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Mass number A\" value={(protonCount + neutronCount).toString()} unit=\"\" color=\"text-rose-500\" />\n                      <StatRow label=\"α energy\" value={alphaEnergy.toFixed(1)} unit=\"MeV\" color=\"text-rose-500\" />\n                      <StatRow label=\"Nuclear radius\" value={(1.2 * Math.pow(protonCount + neutronCount, 1/3)).toFixed(2)} unit=\"fm\" color=\"text-purple-600\" />\n                    </>\n                  )}\n                </div>\n              </div>\n\n              {model === 'bohr' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Hydrogen Spectrum</p>\n                  <div className=\"space-y-1\">\n                    {spectrum.slice(0, 10).map((line, i) => (\n                      <div key={i} className=\"flex items-center gap-2 text-[10px]\">\n                        <div className=\"w-3 h-3 rounded-full shrink-0\" style={{ backgroundColor: line.color }} />\n                        <span className=\"text-gray-500 w-16\">{line.series}</span>\n                        <span className=\"font-mono text-gray-700\">{line.wavelength.toFixed(0)} nm</span>\n                        <span className=\"text-gray-400\">({line.fromN}→{line.toN})</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n              )}\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {Object.keys(CC).map(c => <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <AtomicModelLearning model={model} />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/embed/atomic-models/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicParams, AtomicModel } from '@/lib/physics/atomicModels';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key); return v !== null ? v === '1' : fallback;\n}\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction AtomicModelsEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [model, setModel] = useState<AtomicModel>(() => str(sp, 'model', 'thomson', ['thomson', 'rutherford', 'bohr', 'quantum']));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [zoom, setZoom] = useState(() => num(sp, 'zoom', 1, 0.3, 3));\n  const [showOrbits, setShowOrbits] = useState(() => bool(sp, 'orbits', true));\n  const [showNucleus, setShowNucleus] = useState(() => bool(sp, 'nucleus', true));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'electrons', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showSpectrum, setShowSpectrum] = useState(() => bool(sp, 'spectrum', true));\n  const [showLabels, setShowLabels] = useState(() => bool(sp, 'labels', true));\n  const [showSpin, setShowSpin] = useState(() => bool(sp, 'spin', false));\n  const [showFineStructure, setShowFineStructure] = useState(() => bool(sp, 'fs', false));\n  const [showZeeman, setShowZeeman] = useState(() => bool(sp, 'zeeman', false));\n  const [magneticField, setMagneticField] = useState(() => num(sp, 'B', 0, 0, 5));\n  const [nQuantum, setNQuantum] = useState(() => num(sp, 'n', 1, 1, 4));\n  const [lQuantum, setLQuantum] = useState(() => num(sp, 'l', 0, 0, 3));\n  const [mQuantum, setMQuantum] = useState(() => num(sp, 'm', 0, -3, 3));\n  const [protonCount, setProtonCount] = useState(() => num(sp, 'Z', 1, 1, 92));\n  const [alphaEnergy, setAlphaEnergy] = useState(() => num(sp, 'alphaE', 5, 1, 10));\n\n  const [screening,setScreening]=useState(()=>num(sp,'S',0,0,91));\n  useEffect(()=>{setScreening(s=>Math.min(s,Math.max(0,protonCount-1)));},[protonCount]);\n  const params: AtomicParams = {\n    model, speed, zoom, screening:Math.min(screening,Math.max(0,protonCount-1)), showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure, showZeeman,\n    magneticField, nQuantum, lQuantum, mQuantum, protonCount, neutronCount: 0,\n    electronCount: 1, alphaEnergy,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"af-embed-stage mx-auto max-w-4xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => {\n          const labels: Record<AtomicModel, string> = { thomson: 'Thomson', rutherford: 'Rutherford', bohr: 'Bohr', quantum: 'Quantum' };\n          return (\n            <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n              className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n              {labels[m]}\n            </button>\n          );\n        })}\n      </div>\n\n      <div data-stage-role=\"canvas\"><AtomicModelsCanvas key={resetKey} params={params} onZoomChange={showControls?setZoom:undefined} onParamsChange={showControls?patch=>{if(patch.protonCount!==undefined)setProtonCount(patch.protonCount);if(patch.showOrbits!==undefined)setShowOrbits(patch.showOrbits);if(patch.showElectrons!==undefined)setShowElectrons(patch.showElectrons);if(patch.showNucleus!==undefined)setShowNucleus(patch.showNucleus);if(patch.showEnergyLevels!==undefined)setShowEnergyLevels(patch.showEnergyLevels);if(patch.showLabels!==undefined)setShowLabels(patch.showLabels);if(patch.showSpin!==undefined)setShowSpin(patch.showSpin);if(patch.showSpectrum!==undefined)setShowSpectrum(patch.showSpectrum);if(patch.showFineStructure!==undefined)setShowFineStructure(patch.showFineStructure);if(patch.showZeeman!==undefined)setShowZeeman(patch.showZeeman);if(patch.magneticField!==undefined)setMagneticField(patch.magneticField);if(patch.screening!==undefined)setScreening(patch.screening);if(patch.showProbability!==undefined)setShowProbability(patch.showProbability);if(patch.nQuantum!==undefined)setNQuantum(patch.nQuantum);if(patch.lQuantum!==undefined)setLQuantum(patch.lQuantum);if(patch.mQuantum!==undefined)setMQuantum(patch.mQuantum);}:undefined} isRunning={isRunning} isPaused={isPaused} interactive={showControls} onModelChange={showControls?setModel:undefined} onSpeedChange={showControls?setSpeed:undefined} controls={showControls?{run:()=>{setIsRunning(true);setIsPaused(false);},pause:()=>setIsPaused(v=>!v),reset:()=>{setIsRunning(false);setIsPaused(false);setResetKey(v=>v+1);}}:undefined} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" />\n          <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" />\n          {model === 'rutherford' && <Slider label=\"α energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" />}\n          {model === 'bohr' && showZeeman && <Slider label=\"B field\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" />}\n          {model === 'quantum' && (\n            <>\n              <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" />\n              <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" />\n              <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" />\n            </>\n          )}\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" />Nucleus</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" />Probability</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" />Labels</label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">Powered by <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">A-Factor STEM Studio</a></p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function AtomicModelsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <AtomicModelsEmbedInner />\n    </Suspense>\n  );\n}\n", "checks/atomic-models-layout.cjs": "const fs=require('fs'),vm=require('vm'),path=require('path'),ts=require('typescript'),React=require('react'),{renderToStaticMarkup}=require('react-dom/server'),assert=require('node:assert/strict');\nfunction load(file){file=path.resolve(file);const m={exports:{}};const req=id=>{if(id.endsWith('.css'))return{};if(id.startsWith('@/'))return load('src/'+id.slice(2)+'.ts');if(id.startsWith('.')){const target=path.resolve(path.dirname(file),id);return load(fs.existsSync(target+'.tsx')?target+'.tsx':target+'.ts');}return require(id);};vm.runInNewContext(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText,{module:m,exports:m.exports,require:req,performance,console});return m.exports;}\nconst physics=load('src/lib/physics/atomicModels.ts'),ext=load('src/lib/physics/atomicExtensions.ts'),work=load('src/lib/physics/bohrWorkbench.ts');\nlet s=ext.initialMotion();s=ext.advanceMotion(s,.5,1).state;assert.equal(s.n,1);assert.equal(s.angle,1.1,'electron continuously orbits before a transition');const frozen=ext.advanceMotion(s,0,1);assert.equal(frozen.state,s);s=ext.beginTransition(s,3);const angle=s.transition.angle;s=ext.advanceMotion(s,.4,1).state;assert.equal(s.transition.angle,angle,'straight transition holds azimuth fixed');assert.equal(s.n,1);const done=ext.advanceMotion(s,2,1);assert.equal(done.state.n,3);assert.equal(done.completed.from,1);assert.equal(done.completed.to,3);let down=ext.beginTransition(done.state,1);down=ext.advanceMotion(down,2,1);assert.equal(down.state.n,1);assert(down.completed.to<down.completed.from);\nfor(const to of [2,3,7]){const start=ext.displayOrbit(1,180,1),end=ext.displayOrbit(to,180,1);assert.equal(ext.movingRadius(1,to,.2,180,1),start,'absorption waits for the incoming ray');assert(Math.abs(ext.movingRadius(1,to,1,180,1)-end)<1e-10);assert(Math.abs(ext.movingRadius(to,1,1,180,1)-start)<1e-10);}\nconst q=ext.effectiveCharge(11,8.8);assert(Math.abs(q.Zeff-2.2)<1e-12);assert.equal(ext.effectiveCharge(1,10).sigma,0);assert.equal(ext.effectiveCharge(11,99).Zeff,1);assert.equal(ext.effectiveCharge(11,-2).Zeff,11);assert(physics.bohrEnergy(3,q.Zeff)>physics.bohrEnergy(3,11));assert(physics.bohrRadius(3,q.Zeff)>physics.bohrRadius(3,11));assert(ext.displayOrbit(3,180,q.Zeff)>ext.displayOrbit(3,180,11));assert(Math.abs(physics.transitionWavelength(3,2,q.Zeff)/physics.transitionWavelength(3,2,11)-25)<1e-9);\nassert(Math.abs(ext.zeemanShifts(0)[0].shift)<1e-12);assert(Math.abs(ext.zeemanShifts(3)[2].shift*1e6-173.64)<1e-9);assert.equal(ext.zeemanShifts(5)[2].shift,-ext.zeemanShifts(5)[0].shift);assert(ext.fineSeparation(2,1)*1e6>45&&ext.fineSeparation(2,1)*1e6<46);assert(ext.fineSeparation(3,1)<ext.fineSeparation(2,1));\nlet previous=Infinity;for(let z=.3;z<=3.001;z+=.1){const box=work.atomViewBox(z);assert(box.width<previous);previous=box.width;}const absorb=work.bohrWorkings(1,2,1,2),emit=work.bohrWorkings(1,2,1,1,true);assert(absorb.delta>0&&emit.delta<0);assert.equal(absorb.photon,emit.photon);assert.equal(emit.stored,0);assert.equal(work.scientific(2.467e15),'2.467×10¹⁵');\nconst base={model:'bohr',speed:1,zoom:1,showLabels:true,showOrbits:true,showNucleus:true,showElectrons:true,showEnergyLevels:true,showSpectrum:true,showSpin:true,showFineStructure:true,showZeeman:true,showProbability:true,magneticField:3,nQuantum:1,lQuantum:0,mQuantum:0,protonCount:11,screening:8.8,neutronCount:0,electronCount:1,alphaEnergy:5};\nconst {AtomicModelsCanvas}=load('src/components/simulation/AtomicModelsCanvas.tsx');for(const model of ['bohr','thomson','rutherford','quantum']){const html=renderToStaticMarkup(React.createElement(AtomicModelsCanvas,{params:{...base,model},isRunning:false,isPaused:false,onParamsChange:()=>{},onZoomChange:()=>{}}));assert(html.includes('role=\"img\"'));if(model==='bohr'){for(const text of ['Original Bohr orbital simulation','Run','Auto transitions','Transition target','Physics options','Electron spin','Fine structure','Zeeman effect','Screening constant','Magnetic field B','Zeff','173.64','Absorption and emission spectra','Live worked calculations','Zeff/n'])assert(html.includes(text),text);assert(!html.includes('Play full absorption'));}if(model==='quantum'){for(const text of ['Quantum n','Quantum l','Quantum m','Quantum parameters','radial /'])assert(html.includes(text),text);}if(model==='thomson')assert(html.includes('plum-pudding'));}\nconst original=fs.readFileSync('src/components/simulation/BohrRadiationLab.tsx','utf8');assert(original.includes('if(t.to<t.from)'),'emission rays are created only for downward transitions');assert(original.includes('p.showFineStructure'));assert(original.includes('p.showZeeman'));assert(original.includes('p.showSpectrum'));assert(original.includes('p.showSpin'));assert(original.includes('p.screening'));assert(!original.includes('BohrCalculations lower={lower}'));\nconsole.log('PASS: original circular motion and straight transitions, absorption arrival, downward-only emission, effective-charge shielding, normal Zeeman B-dependence, fine structure, full Bohr controls/spectrum/readouts, zoom and all four model renders.');\n\nconst {ATOMIC_LESSONS,AtomicModelLearning}=load('src/components/simulation/AtomicModelLearning.tsx');for(const model of ['bohr','thomson','rutherford','quantum']){assert(ATOMIC_LESSONS[model].notes.length>=4);assert(ATOMIC_LESSONS[model].tasks.length>=4);const html=renderToStaticMarkup(React.createElement(AtomicModelLearning,{model}));assert(html.includes(ATOMIC_LESSONS[model].title));assert(html.includes('Worked example'));assert(html.includes('Check your reasoning'));}assert(original.includes('photonWave(ctx,px,py,a,lightColour('));assert(original.includes('photonWave(ctx,ray.x,ray.y,ray.angle,lightColour('));console.log('PASS: classroom quantum controls, matching photon colours, paired spectra and distinct model teaching/investigations.');\n", "src/components/simulation/AtomicModelLearning.tsx": "import type {AtomicModel} from '@/lib/physics/atomicModels';\ntype Lesson={title:string;aim:string;notes:string[];demo:string;worked:string;tasks:[string,string][]};\nexport const ATOMIC_LESSONS:Record<AtomicModel,Lesson>={\n thomson:{title:'Thomson: charge spread through the atom',aim:'Explain the plum-pudding picture and distinguish electrical neutrality from an absence of charge.',notes:[\n 'The shaded positive sphere represents positive charge distributed throughout the atom. The embedded negative electrons are the plums. This model contains no compact central positive nucleus; the sphere is not an electron orbit.',\n 'For a neutral atom, total positive charge +Ze balances electron charge −Ne when Ne=Z. A neutral object can contain many charges. Removing an electron leaves a positive ion without changing the positive charge.',\n 'The electron animation is illustrative motion inside the proposed positive material. It is not measured electron trajectories or evidence that the model correctly predicts atomic spectra.',\n 'Ask learners what a spread-out positive charge would imply for an energetic positive probe. Contrast gentle cumulative deflection with the rare large-angle events that challenged this picture. Thomson’s model cannot account for those events with a tiny dense scattering centre.'\n ],demo:'Identify the positive background and negative electrons. Pause and sketch the charge distribution. Switch to Rutherford and ask what evidence requires the positive charge to be concentrated instead.',worked:'If Z=6 and Ne=5, Q=(Z−Ne)e=+e=+1.602×10⁻¹⁹ C. One electron must be added for neutrality; adding a neutron would not restore it.',tasks:[\n ['Draw and annotate the model. Where are the two signs of charge, and where is its nucleus?','Positive charge fills the sphere; negative electrons are embedded. There is no compact nucleus in this model.'],\n ['A proposed atom has +8e and ten electrons. Find its net charge and explain the sign.','Q=(8−10)e=−2e=−3.204×10⁻¹⁹ C. Two excess electrons give a negative ion.'],\n ['Predict whether a diffuse positive sphere or a concentrated nucleus better explains an alpha particle returning towards its source. Explain.','A concentrated positive nucleus produces a strong repulsive force in a close approach; diffuse charge cannot explain the observed rare large deflections in the same way.'],\n ['Write a claim, evidence and limitation paragraph comparing this model with Rutherford.','Claim: atomic charge is separated. Evidence: electrons exist. Limitation: diffuse positive charge fails to explain large-angle scattering; Rutherford concentrates positive charge in the nucleus.']\n ]},\n rutherford:{title:'Rutherford: use scattering as evidence',aim:'Connect alpha-particle deflection to the concentration of positive charge and compare controlled trials.',notes:[\n 'Incoming alpha particles carry positive charge. The positive nucleus repels them. Most probes pass far from the small nucleus and have little deflection; a close encounter can cause a large deflection. No material planetary orbit is being traced by the incoming probe.',\n 'Impact parameter is the perpendicular offset of the incoming path from the nuclear centre. Small offsets permit a closer approach. This display uses illustrative trajectories, so do not infer a measured cross-section or real nuclear size from its pixels.',\n 'Compare alpha energies while holding nuclear charge fixed. A faster, more energetic probe is generally deflected less at the same impact parameter. Compare Z while holding energy fixed: stronger nuclear repulsion gives greater deflection.',\n 'The experiment supports a small positive nucleus and an atom whose volume is mostly empty space. It does not by itself establish neutron composition or quantised electron states. Classical orbiting electrons would radiate; atomic stability remains a problem for this model.'\n ],demo:'Run at a fixed Z and low alpha energy, record several tracks, then repeat at higher energy. Compare similar incoming offsets rather than unrelated random tracks. Repeat with larger Z and discuss the limitation of a qualitative sample.',worked:'For a head-on approach to gold, use k=1.44 MeV·fm and charges 2e and 79e. At 5 MeV, rmin=(1.44×2×79)/5≈45.5 fm, neglecting recoil. Doubling the energy halves this turning distance.',tasks:[\n ['Explain why most alpha particles pass through while a few turn through large angles.','Most miss the tiny nucleus by a large distance. A few approach close enough for strong Coulomb repulsion.'],\n ['Predict the effect of increasing alpha energy at fixed Z and similar incoming offset. Record observations and explain any trial-to-trial differences.','Deflection generally decreases. Different randomly sampled offsets can conceal the trend; use comparable offsets and multiple trials.'],\n ['Calculate the head-on turning distance for a 10 MeV alpha particle approaching gold using k=1.44 MeV·fm.','rmin=1.44×158/10=22.75 fm, assuming a stationary heavy nucleus and no recoil.'],\n ['Which problem did Bohr address that the nuclear model left unresolved?','Stable atoms and discrete spectra: classical accelerating orbital charges should continuously radiate, unlike stationary quantum states.']\n ]},\n bohr:{title:'Bohr: excitation, relaxation and spectral lines',aim:'Use signed atomic energy changes and positive photon energies to explain absorption and emission.',notes:[\n 'The moving dot represents the electron in a permitted Bohr orbit. Larger n means a less negative bound energy. The straight radial jump and the wavy arrow are teaching symbols: an electron does not follow a measured classical path through forbidden stationary energies.',\n 'Turn automatic transitions off to control the experiment. Select a higher target n and press Transition: the incoming photon precedes excitation. Select a lower target: relaxation releases an outgoing photon. The displayed ΔE atom is positive for absorption and negative for emission; Eγ=|ΔE| is always positive.',\n 'A dark line on a continuous rainbow marks light removed at an allowed absorption wavelength. A bright line on black marks emitted light. Reverse transitions between the same pair have the same photon energy and wavelength. Many transitions lie in UV or IR, so they must not be drawn as a visible spectral line.',\n 'With screening, the chosen constant gives Zeff=Z−σ. The hydrogenic approximation uses Eₙ=−13.606 Zeff²/n² eV and rₙ=0.529 n²/Zeff Å. It is not an accurate many-electron calculation. Zoom changes display size, not these physical values.',\n 'Enable fine structure and Zeeman separately. The normal-Zeeman illustration separates components in proportion to B with μB B shifts; fine structure illustrates small relativistic corrections. Splittings are enlarged and drawn separately, not a complete combined spin-orbit spectrum or selection-rule calculation.'\n ],demo:'Set Z=1 and σ=0. Excite 1→3, then emit 3→2 to see a visible red line. Compare 2→3 absorption with 3→2 emission. Pause to read both signed ΔE and positive Eγ. Then vary B and screening independently.',worked:'For hydrogen 3→2: Ei=−13.606/9=−1.5118 eV; Ef=−13.606/4=−3.4015 eV. ΔE=−1.8897 eV, Eγ=1.8897 eV, λ≈1240/1.8897≈656.2 nm (red). The reverse transition absorbs the same energy.',tasks:[\n ['Measure 3→2 and 2→3. Compare ΔE, photon energy, wavelength and the two spectrum backgrounds.','ΔE changes sign; Eγ≈1.8897 eV and λ≈656.2 nm remain the same. Emission is bright on black; absorption removes that wavelength from a continuum.'],\n ['Calculate the wavelength for hydrogen 2→1. Should a visible coloured line appear?','Eγ=13.606(1−1/4)=10.2045 eV; λ≈121.5 nm, ultraviolet. No line belongs in the visible 380–780 nm band.'],\n ['At fixed n, change Zeff from 2 to 1 using shielding. Predict energy magnitude and radius ratios before observing.','Binding-energy magnitude falls to one quarter; radius doubles. A given transition wavelength increases by a factor of four.'],\n ['Predict the normal-Zeeman component shift at B=2 T using μB=5.788×10⁻⁵ eV/T, then set B=0.','Shifts are −115.76, 0 and +115.76 μeV. At B=0 the normal-Zeeman components coincide. This is separate from fine structure.'],\n ['Explain two limitations of the displayed orbital jump and screening.','The radial path is symbolic, not a literal electron trajectory. A chosen constant Zeff is an approximation and cannot reproduce a general many-electron atom.']\n ]},\n quantum:{title:'Quantum model: probability, orbitals and nodes',aim:'Distinguish an orbital from an orbit and use valid quantum numbers to investigate probability patterns.',notes:[\n 'The coloured slice represents relative probability density |ψ|² in a plane, not an electron travelling through a cloud. Repeated position measurements on identically prepared atoms build up a distribution. The animated brightness is a display aid; a stationary-state probability density does not pulse with time.',\n 'Use the classroom header controls n, l and m. Allowed values are n=1,2,…, l=0,…,n−1 and m=−l,…,+l. Changing n or l also constrains the remaining controls so an invalid state cannot be selected.',\n 'The letters s, p, d and f correspond to l=0,1,2,3. A hydrogenic orbital has n−l−1 radial nodes and l angular nodes. A slice can miss features of a three-dimensional orbital; do not interpret every blank pixel as an exact mathematical node.',\n 'The radial probability plot concerns the probability in spherical shells, whereas the coloured slice shows local relative density. A shell’s volume factor matters: the radius of greatest radial probability is not necessarily the point of greatest local density.',\n 'The hydrogenic energy depends on n and Z, Eₙ=−13.606 Z²/n² eV. At a fixed n there are n² spatial states excluding spin in the ideal Coulomb model. This implementation uses a simplified orbital visualization, not a full numerical Schrödinger solver; compare patterns qualitatively rather than treating colours as calibrated probabilities.'\n ],demo:'Compare 1s, 2s and 2p with the header controls. Ask learners to predict node counts first. Hold n and l fixed while changing m, then discuss which changes the chosen slice can reveal. Use Run/Pause to distinguish the display animation from an electron orbit.',worked:'For n=3,l=1: the orbital is 3p; m can be −1,0,+1. It has one radial node and one angular node. At Z=1 its hydrogenic energy is −13.606/9=−1.5118 eV. Three m values describe three spatial states for this subshell, excluding spin.',tasks:[\n ['List all allowed (l,m) pairs for n=2. How many spatial states are there, excluding spin?','(0,0), (1,−1), (1,0), (1,1): four states, agreeing with n²=4.'],\n ['Compare predicted node counts for 1s, 2s, 2p and 3d, then inspect the slices and radial plots.','Radial/angular counts: 1s 0/0; 2s 1/0; 2p 0/1; 3d 0/2. Explain any features that a particular slice or simplified renderer does not resolve.'],\n ['Is (n,l,m)=(2,2,0) valid? Is (3,1,2) valid? Give the violated rule.','Neither is valid: l must be less than n; |m| must not exceed l.'],\n ['Calculate the hydrogenic energy at n=2,Z=2 and compare with n=2,Z=1.','E=−13.606×4/4=−13.606 eV, versus −3.4015 eV for hydrogen: four times the binding-energy magnitude.'],\n ['Explain why a probability cloud and a radial probability graph need different interpretations.','Density refers to probability per volume locally; radial probability includes contributions over a spherical shell. Neither is a classical electron path.']\n ]}\n};\nexport function AtomicModelLearning({model}:{model:AtomicModel}){const lesson=ATOMIC_LESSONS[model];return <section className=\"space-y-4\" aria-label={`${lesson.title} learning activities`}><div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\"><h2 className=\"font-semibold text-amber-900\">Teacher notes · {lesson.title}</h2><p className=\"my-3 text-sm text-amber-900\"><strong>Learning goal:</strong> {lesson.aim}</p>{lesson.notes.map(note=><p className=\"my-3 text-sm leading-relaxed text-amber-950\" key={note}>{note}</p>)}<h3 className=\"font-semibold text-amber-900\">Demonstration and discussion</h3><p className=\"my-2 text-sm text-amber-950\">{lesson.demo}</p><h3 className=\"font-semibold text-amber-900\">Worked example</h3><p className=\"my-2 text-sm text-amber-950\">{lesson.worked}</p></div><div className=\"rounded-2xl border border-indigo-100 bg-white p-4\"><h2 className=\"font-semibold text-indigo-950\">Student investigation · {lesson.title}</h2><p className=\"my-2 text-sm text-slate-700\">Predict first, record your settings and observations, then explain using the model. Submit a labelled sketch, calculations with units, and one limitation.</p><ol className=\"list-decimal space-y-4 pl-5\">{lesson.tasks.map(([question,answer])=><li className=\"text-sm text-slate-800\" key={question}><p>{question}</p><details className=\"mt-2 rounded border border-slate-200 p-2\"><summary className=\"cursor-pointer font-medium\">Check your reasoning</summary><p className=\"mt-2\">{answer}</p></details></li>)}</ol></div><p className=\"text-xs text-slate-600\">Further reading: <a className=\"underline\" href=\"https://openstax.org/books/university-physics-volume-3/pages/6-4-bohrs-model-of-the-hydrogen-atom\">OpenStax: Bohr model and spectra</a> · <a className=\"underline\" href=\"https://openstax.org/books/university-physics-volume-3/pages/8-1-the-hydrogen-atom\">Hydrogen atom and quantum states</a>. Split-level drawings and orbital slices are teaching approximations.</p></section>;}\n"},expected={"src/components/simulation/AtomicModelsCanvas.tsx": "30f1130d8a1dfadd12b7f705699b87508a38f3929ceb887b3a52e46c42e22091", "src/components/simulation/BohrRadiationLab.tsx": "a02d02f45e3825d5f260a48f92e1ad5425c89638c8980a23d45b438abf561cda", "src/components/simulation/atomic-models.css": "b701819ccb6de9a9d86ffade28ff6a7fb7e0420391aab3cf1adf70d8eb3c5c32", "src/app/simulations/atomic-models/page.tsx": "aaf31509270be86400a71310a1c337635d085005772110802a00b3bbcfe828d0", "src/app/embed/atomic-models/page.tsx": "ed5a1e4bedcb5f894c8a35187b143f7ae25931141c9bc3d4d3947c400e761132", "checks/atomic-models-layout.cjs": "c425b2fa7cfed24a10d6e6349e1d5914e6a25143f5d111da2d0a7a7cf15b140a", "src/components/simulation/AtomicModelLearning.tsx": null};
